import { MAIN_LIGHT_DEFAULTS } from '@nudo-tsl/core'
import type { MainLightComponent, MaterialAssignment } from '@nudo-tsl/core'
import { uniformExpression } from './code-backend'
import { collectDependencies } from './code-expression'
import type { CodeExpression, HoistedValue } from './code-expression'
import { LIGHTS_OBJECT, MAIN_LIGHT_KEYS, MAIN_LIGHT_ORDER } from './code-facade'
import { HELPER_ORDER, TSL_HELPERS } from './tsl-helpers'

const INDENT = '  '
const SEPARATOR = ' · '
const TSL_MODULE = 'three/tsl'
const THREE_MODULE = 'three'
const GENERATED_NOTICE =
  '// Generated by nudo-tsl from a node graph. Edit the graph, not this file.'
const NEUTRAL_TEXTURE = 'neutralTexture'
const NEUTRAL_GREY = 128
const OPAQUE_ALPHA = 255
const TEXTURE_THREE_IMPORTS = ['DataTexture', 'RGBAFormat', 'UnsignedByteType'] as const
const NEUTRAL_TEXTURE_SOURCE = [
  '// The 1x1 grey (0.5) every texture node shows until a texture is assigned.',
  `const ${NEUTRAL_TEXTURE} = new DataTexture(`,
  `${INDENT}new Uint8Array([${String(NEUTRAL_GREY)}, ${String(NEUTRAL_GREY)}, ${String(NEUTRAL_GREY)}, ${String(OPAQUE_ALPHA)}]),`,
  `${INDENT}1,`,
  `${INDENT}1,`,
  `${INDENT}RGBAFormat,`,
  `${INDENT}UnsignedByteType,`,
  ')',
  `${NEUTRAL_TEXTURE}.needsUpdate = true`,
].join('\n')
const textureNotice = (example: string): string =>
  [
    "// Texture nodes for the graph's textures, showing the neutral grey. Assign a THREE.Texture",
    `// to one with its value, for example \`textures.${example}.value = myTexture\`.`,
  ].join('\n')

const MAIN_LIGHT_NOTICE = [
  "// Main Light: keep in step with your scene's key DirectionalLight, e.g.",
  `${LIGHTS_OBJECT}.${MAIN_LIGHT_KEYS.direction}.value.copy(light.position).normalize();`,
  `${LIGHTS_OBJECT}.${MAIN_LIGHT_KEYS.color}.value.setFromColor(light.color).multiplyScalar(light.intensity)`,
].join(' ')

/** How to put the outline pass on a mesh: the same geometry, drawn again with this material. */
const OUTLINE_USAGE = [
  '// Outline: draw the geometry again with this, e.g. mesh.add(new Mesh(mesh.geometry, outline))',
  '// const outline = Object.assign(new MeshBasicNodeMaterial(), outlineNodes, outlineMaterialSettings)',
]
const OUTLINE_SIDE = 'BackSide'

export type MaterialClass =
  'MeshStandardNodeMaterial' | 'MeshBasicNodeMaterial' | 'MeshPhysicalNodeMaterial'

export interface NamedExpression {
  readonly name: string
  readonly expression: CodeExpression
}

/** Everything the module prints, already resolved from the graph. */
export interface ModulePlan {
  /** Printed as is, e.g. `r186`. */
  readonly threeVersion: string
  readonly materialClass: MaterialClass
  /** Short phrases for the header, e.g. `transparent`, `double-sided`. */
  readonly surfaceHints: readonly string[]
  readonly uniforms: readonly NamedExpression[]
  readonly texturePlaceholders: readonly string[]
  /** The Main Light components the graph reads; each becomes a `lights` uniform. */
  readonly lights: readonly MainLightComponent[]
  readonly entries: readonly MaterialAssignment<CodeExpression>[]
  /** The outline pass's properties; empty while the master's Outline is off. */
  readonly outline: readonly MaterialAssignment<CodeExpression>[]
  readonly transparent: boolean
  readonly doubleSided: boolean
}

const printObject = (name: string, lines: readonly string[]): string =>
  `export const ${name} = {\n${lines.map((line) => `${INDENT}${line},`).join('\n')}\n}`

const MAX_LINE_WIDTH = 100

/** One line when it fits, otherwise one name per line (the way prettier lays imports out). */
function printImport(names: Iterable<string>, from: string): string {
  const sorted = [...names].sort()
  const oneLine = `import { ${sorted.join(', ')} } from '${from}'`
  if (oneLine.length <= MAX_LINE_WIDTH) return oneLine
  return `import {\n${sorted.map((name) => `${INDENT}${name},`).join('\n')}\n} from '${from}'`
}

const printDeclaration = ({ name, value }: HoistedValue): string => `const ${name} = ${value.code}`

function printHeader(plan: ModulePlan): string {
  const lines = [
    GENERATED_NOTICE,
    `// three ${plan.threeVersion}${SEPARATOR}${plan.materialClass}`,
    `// Surface: ${plan.surfaceHints.join(SEPARATOR)}`,
    `// Apply: Object.assign(new ${plan.materialClass}(), nodes, materialSettings)`,
    ...(plan.outline.length > 0 ? OUTLINE_USAGE : []),
  ]
  return lines.join('\n')
}

/** `import` lines: the `three/tsl` names the module uses, and the side constant when needed. */
function printImports(tslNames: ReadonlySet<string>, threeNames: readonly string[]): string {
  const lines = [
    ...(tslNames.size > 0 ? [printImport(tslNames, TSL_MODULE)] : []),
    ...(threeNames.length > 0 ? [printImport(threeNames, THREE_MODULE)] : []),
  ]
  return lines.join('\n')
}

/** One shared uniform per Main Light component read, starting at the preview's key light. */
const lightUniformsOf = (components: readonly MainLightComponent[]): readonly NamedExpression[] =>
  MAIN_LIGHT_ORDER.filter((component) => components.includes(component)).map((component) => ({
    name: MAIN_LIGHT_KEYS[component],
    expression: uniformExpression(
      { type: 'vec3', value: MAIN_LIGHT_DEFAULTS[component] },
      undefined,
    ),
  }))

const printNamedExpressions = (name: string, expressions: readonly NamedExpression[]): string =>
  printObject(
    name,
    expressions.map(({ name: key, expression }) => `${key}: ${expression.code}`),
  )

const printAssignments = (
  name: string,
  assignments: readonly MaterialAssignment<CodeExpression>[],
): string =>
  printObject(
    name,
    assignments.map(({ property, expression }) => `${property}: ${expression.code}`),
  )

/** Prints the plan as a JS module. Output is stable: the same plan always prints the same text. */
export function printModule(plan: ModulePlan): string {
  const lights = lightUniformsOf(plan.lights)
  const roots = [
    ...plan.uniforms.map(({ expression }) => expression),
    ...lights.map(({ expression }) => expression),
    ...plan.entries.map((entry) => entry.expression),
    ...plan.outline.map((entry) => entry.expression),
  ]
  const dependencies = collectDependencies(roots)
  const helpers = HELPER_ORDER.filter((name) => dependencies.helpers.has(name))
  const tslNames = new Set([
    ...dependencies.imports,
    ...helpers.flatMap((name) => TSL_HELPERS[name].imports),
  ])
  const sideConstant = plan.doubleSided ? 'DoubleSide' : 'FrontSide'
  const [firstTexture] = plan.texturePlaceholders
  const hasTextures = firstTexture !== undefined
  if (hasTextures) tslNames.add('texture')
  const hasOutline = plan.outline.length > 0
  const threeNames = [
    ...(hasOutline ? [OUTLINE_SIDE] : []),
    sideConstant,
    ...(hasTextures ? TEXTURE_THREE_IMPORTS : []),
  ]

  const sections = [
    `${printHeader(plan)}\n${printImports(tslNames, threeNames)}`,
    plan.uniforms.length > 0 ? printNamedExpressions('uniforms', plan.uniforms) : '',
    lights.length > 0
      ? `${MAIN_LIGHT_NOTICE}\n${printNamedExpressions(LIGHTS_OBJECT, lights)}`
      : '',
    hasTextures ? NEUTRAL_TEXTURE_SOURCE : '',
    hasTextures
      ? [
          textureNotice(firstTexture),
          printObject(
            'textures',
            plan.texturePlaceholders.map((name) => `${name}: texture(${NEUTRAL_TEXTURE})`),
          ),
        ].join('\n')
      : '',
    // Helpers that share a source (the 2D and 3D cell searches) declare it once.
    ...new Set(helpers.map((name) => TSL_HELPERS[name].source)),
    dependencies.declarations.map(printDeclaration).join('\n'),
    printAssignments('nodes', plan.entries),
    printObject('materialSettings', [
      `transparent: ${String(plan.transparent)}`,
      `side: ${sideConstant}`,
    ]),
    hasOutline ? printAssignments('outlineNodes', plan.outline) : '',
    hasOutline ? printObject('outlineMaterialSettings', [`side: ${OUTLINE_SIDE}`]) : '',
    'export default nodes',
  ]
  return `${sections.filter((section) => section.length > 0).join('\n\n')}\n`
}
